# 
import os, stat, subprocess, time, signal
os.makedirs('/opt/agentos/state/run', exist_ok=True)
dout = open('/opt/agentos/daemon.out', 'wb')
d = subprocess.Popen(['/opt/agentos-bin/thox-agentd', '--state-dir', '/opt/agentos/state', '--agents-dir', '/opt/agentos/config/agents', '--trust-dir', '/opt/agentos/config/trust'], stdout=dout, stderr=subprocess.STDOUT, stdin=subprocess.DEVNULL)
print('daemon_pid', d.pid)
time.sleep(3)
d.send_signal(signal.SIGTERM)
print('daemon_exit', d.wait(timeout=15))
print("m4-ok")
